function wrongAction() {
  if (state.status !== 'playing') return;
  emit('action_rejected', {});
  state.progress = 0;
  emit('progress_reset', {});
  state.lives -= 1;
  state.last_action = 'wrong';
  if (state.lives <= 0) {
    state.lives = 0;
    saveState();
    state.status = 'lost';
    emit('game_lost', {});
  } else {
    saveState();
  }
}
